          __comment: 'The Singing plate preset in 3D: a million grains on a round plate (Pattern: Chladni round) lying flat at the emitter, seen by a camera tilted 50° above it that slowly circles (Drift), with a little depth of field (Blur). Mode from Sound picks the rings (M) and spokes (N); the sand slides onto the still lines and jumps on every hit.',
